use semio_framework_value_native_owned::{DslValue,NativeDecodeConstructionRecipient,NativeDecodeControl,NativeReceive,NativeReceiver,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,RetirementDemand,ValueError,owned::set::NativeSetReceiver,retained_clone::{RetainedCloneSource,retained_clone_grant_admits},retirement::{RetireOwned,controlled::ControlledRetirement}};
use semio_framework_value_ordered::OrderedSet;
use semio_framework_value_testing_allocator::observe_retirement_allocations as heap;
const BODY:usize=32768;
fn grant(d:RetirementDemand)->RetainedCloneGrant{assert!(d.copy_bytes<=BODY,"original set header exceeds native policy: {d:?}");RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn source(v:DslValue)->RetainedCloneSource<DslValue>{let d=RetainedCloneSource::<DslValue>::owned_constructor_demand::<()>();RetainedCloneSource::admit_owned(v,(),RetainedCloneGrant{maximum_copy_bytes:RetainedCloneSource::<DslValue>::constructor_copy_bytes(),..grant(RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()})}).unwrap_or_else(|_|panic!("actual set source admission")).0}
fn drain<T:RetireOwned>(v:T){let mut r=ControlledRetirement::new(v).unwrap_or_else(|_|panic!("actual set owner supports retirement"));for _ in 0..100000{if r.terminal_is_empty(){return}let g=grant(r.next_demand(BODY).unwrap());let(p,h)=heap(||r.step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}panic!("native set physical closure stalled")}
fn denials(g:RetainedCloneGrant)->Vec<RetainedCloneGrant>{let mut out=vec![RetainedCloneGrant{maximum_items:0,..g}];if g.maximum_copy_bytes>0{out.push(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-1,..g})}if g.maximum_capacity_bytes>0{out.push(RetainedCloneGrant{maximum_capacity_bytes:g.maximum_capacity_bytes-1,..g})}if g.maximum_release_bytes>0{out.push(RetainedCloneGrant{maximum_release_bytes:g.maximum_release_bytes-1,..g})}if g.maximum_depth>0{out.push(RetainedCloneGrant{maximum_depth:g.maximum_depth-1,..g})}out}
struct Turn{grant:RetainedCloneGrant,issued:bool}
impl NativeDecodeConstructionRecipient for Turn{fn grant(&mut self,d:RetirementDemand)->Result<RetainedCloneGrant,ValueError>{assert!(!self.issued);assert!(retained_clone_grant_admits(self.grant,d));self.issued=true;Ok(self.grant)}fn accept(&mut self,g:RetainedCloneGrant,p:RetainedCloneProgress)->Result<(),ValueError>{assert!(self.issued);assert_eq!(g,self.grant);assert!(p.fits(g));Ok(())}}
fn advance(r:&mut NativeSetReceiver<DslValue>,s:&RetainedCloneSource<DslValue>,c:&mut NativeDecodeControl<'_>,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{c.with_construction_recipient(&mut Turn{grant:g,issued:false},|c|r.advance(s.borrow(),c,BODY,g))}
#[test]fn original_set_receiving_matches_fixture_admits_every_insert_and_closes_every_partial_owner(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();
 for case in law["cases"].as_array().unwrap(){for cut in law["cancelCuts"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).chain(std::iter::once(100000)){
  let s=source(DslValue::Array(case["members"].as_array().unwrap().iter().map(|m|DslValue::String(m.as_str().unwrap().into())).collect()));
  let g=grant(<OrderedSet as NativeReceive<DslValue>>::receive_birth_demand());let((mut r,p),h)=heap(||<OrderedSet as NativeReceive<DslValue>>::begin_receive(g).unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let mut callback=|_|true;let mut c=NativeDecodeControl::new(1<<26,&mut callback);
  for turn in 0..cut{if r.output_ready(){break}let d=r.demands(s.borrow(),BODY).unwrap();let g=grant(d);for denied in denials(g){let(p,h)=heap(||advance(&mut r,&s,&mut c,denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.demands(s.borrow(),BODY).unwrap(),d)}let(p,h)=heap(||advance(&mut r,&s,&mut c,g).unwrap());assert!(p.progress().fits(g),"actual set receipt {:?} exceeds {g:?}",p.progress());assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes),"unadmitted set allocation on turn {turn}")}
  if r.output_ready(){let g=grant(r.take_demand().unwrap());let((set,p),h)=heap(||r.take(g).unwrap().unwrap());assert!(p.fits(g));assert_eq!(h,(p.retained_capacity_bytes,p.released_bytes));let members:Vec<_>=set.iter().map(|m|serde_json::json!(m)).collect();assert_eq!(serde_json::Value::Array(members),case["expected"]);let oracle:std::collections::BTreeSet<&str>=case["members"].as_array().unwrap().iter().map(|m|m.as_str().unwrap()).collect();assert!(set.iter().map(String::as_str).eq(oracle.into_iter()));drain(set)}else{assert_ne!(cut,100000,"actual set preparation stalled")}
  r.begin_close();for _ in 0..100000{if r.terminal_is_empty(){break}let d=r.close_demands(BODY).unwrap();let g=grant(d);for denied in denials(g){let(p,h)=heap(||r.close_step(denied).unwrap());assert_eq!(p.progress(),Default::default());assert_eq!(h,(0,0));assert_eq!(r.close_demands(BODY).unwrap(),d)}let(p,h)=heap(||r.close_step(g).unwrap());assert!(p.progress().fits(g));assert_eq!(h,(p.progress().retained_capacity_bytes,p.progress().released_bytes));}assert!(r.terminal_is_empty());drain(s);
 }}
}
